// A ENTRADA do pacote — a instância WEB da linguagem, em uma linha.
//
//     import 'diletta-design-system-web';                       // registra tudo
//     import { registra } from 'diletta-design-system-web';     // ou escolhe
//
// E a cor, que é obrigatória e vem antes de qualquer peça:
//
//     <link rel="stylesheet" href=".../tokens/generated/cps-tokens.css">
//     <link rel="stylesheet" href=".../tokens/generated/cps-papeis.css">
//
// Sem as duas folhas as peças renderizam sem tinta — `var(--cps-…)` sem valor não
// é erro, é silêncio. Foi assim que o CSS deste repo ficou morto por semanas.
