/// Os custom elements que este pacote define. Importar o módulo já registra —
/// `customElements.define` roda no corpo de cada arquivo. Esta lista existe para
/// quem precisa SABER o que foi registrado sem inspecionar o registry.
export const elementos = [
  'diletta-avatar',
  'diletta-breadcrumb',
  'diletta-button',
  'diletta-data-cell',
  'diletta-data-column-header',
  'diletta-data-header-row',
  'diletta-data-list',
  'diletta-data-row',
  'diletta-icon-button',
  'diletta-divider',
  'diletta-input',
  'diletta-pagination',
  'diletta-rail-item',
  'diletta-segmented-control',
  'diletta-spot-icon',
  'diletta-status-tag',
  'diletta-tab-item',
  'diletta-input-chip',
  'diletta-tabs',
  'diletta-file-card',
  'diletta-text-link',
  'diletta-web-stepper-node',
  'diletta-web-top-bar',
  'diletta-tooltip',
  'diletta-toast',
];

/// Espera todos ficarem prontos. Útil para quem renderiza no servidor e precisa
/// do primeiro paint com as peças já definidas.
export const prontos = () =>
  Promise.all(elementos.map((t) => customElements.whenDefined(t)));
